bsc-scope() { local globs="${BSC_SCOPE_GLOBS:-}"; [ "$globs" = "__bsc_deny_all__" ] && { __bsc_perm scope "" "code:none — no write scope"; echo "blocked: this session is code:none (no write scope) -- file writes are denied (#1916)" >&2; return 2; }; [ -z "$globs" ] && return 0; local root="${BSC_REPO_ROOT:-}"; local j fp g; j="$(cat)"; fp="$(printf '%s' "$j" | __bsc_jstr 'file_path|notebook_path')"; [ -z "$fp" ] && return 0; fp="${fp//\\//}"; fp="$(printf '%s' "$fp" | tr -s '/')"; [ -n "$root" ] && case "$fp" in "$root"/*) fp="${fp#"$root"/}" ;; esac; fp="${fp#./}"; set -f; for g in $globs; do case "$fp" in $g) set +f; return 0 ;; esac; done; set +f; __bsc_perm scope "$fp" "outside the write scope"; echo "blocked: '$fp' is outside this session's write scope (#1297) — allowed: $globs" >&2; return 2; }
